            "Updates the checkout SDK and refreshes the lockfile.",
            0,
            &["m3"][..],
            1,
            "5 hours ago",
            12,
            12,
            2,
        ),
        (
            "f2",
            "c7a3e52",
            "Add Apple Pay button",
            "Shows Apple Pay where supported and falls back to the card form.",
            1,
            &["f1"][..],
            0,
            "Yesterday",
            96,
            8,
